def _parsed_label_in_index(self, label: str) -> npt.NDArray[np.bool_]:
    """
    Return a boolean mask indicating whether the string `label`, parsed
    with its resolution, matches any element of the index.
    """
    parsed, reso = self._parse_with_reso(label)
    lower, upper = self._parsed_string_to_bounds(reso, parsed)
    return (lower <= self) & (self <= upper)

